package com.yuegang.zhihui.ai.infrastructure;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.HttpServer;import com.yuegang.zhihui.ai.application.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.search.api.SearchHit;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.*;
class AiGatewaysTest{HttpServer server;String base;@BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress(0),0);base="http://localhost:"+server.getAddress().getPort();server.createContext("/chat/completions",x->reply(x,"{\"choices\":[{\"message\":{\"content\":\"model answer\"}}]}"));server.createContext("/internal/v1/search/hybrid",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":[{\"documentId\":\"1\",\"chunkId\":\"2\",\"title\":\"t\",\"excerpt\":\"e\",\"lexicalScore\":1,\"vectorScore\":2,\"finalScore\":3}],\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/api/v1/products/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"name\":\"snack\"},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/internal/v1/inventory/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"availableQuantity\":18},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/api/v1/orders/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"status\":\"PAID\"},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.start();}@AfterEach void stop(){server.stop(0);}static void reply(com.sun.net.httpserver.HttpExchange x,String s)throws java.io.IOException{byte[]b=s.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().add("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();}
@Test void modelRetrievalCommerceAndMetrics(){assertThatThrownBy(()->new DoubaoModelGateway(base,"","m")).isInstanceOf(IllegalStateException.class);ModelGateway model=new DoubaoModelGateway(base,"key","m");assertThat(model.answer("s","u")).isEqualTo("model answer");byte[]secret="01234567890123456789012345678901".getBytes();var retrieval=new HttpRetrievalGateway(base,secret);assertThat(retrieval.search("q",null,5)).singleElement().extracting(SearchHit::finalScore).isEqualTo(3d);var tools=new CommerceToolGateway(base,base,secret,new ObjectMapper());assertThat(tools.product("3").digest()).hasSize(64);assertThat(tools.ownOrder(7,"8").name()).isEqualTo("OWN_ORDER_LOOKUP");var registry=new SimpleMeterRegistry();var measuredModel=new MeasuredModelGateway(model,registry);assertThat(measuredModel.answer("s","u")).isEqualTo("model answer");var measuredRetrieval=new MeasuredRetrievalGateway(retrieval,registry);assertThat(measuredRetrieval.search("q",null,2)).hasSize(1);var governance=mock(AiGovernanceService.class);when(governance.activeSystemPrompt()).thenReturn("governed");assertThat(new GovernedModelGateway((s,u)->s+u,governance).answer("x","u")).isEqualTo("governedu");}
}
